// frontend/src/router/index.js
import { createRouter, createWebHistory } from "vue-router";
import Login from "@/views/login/LoginPage.vue";
import Home from "@/views/home/HomePage.vue";
import Register from "@/views/login/RegisterPage.vue";
import ForgetPassword from "@/views/login/ForgetpasswordPage.vue";
import ProductPage from "@/views/product/ProductPage.vue"; // 导入商品详情页
import UserPage from "@/views/user/UserPage.vue"; // 导入个人页面
import CartPage from "@/views/user/CartPage.vue";
import OrderPage from "@/views/user/OrderPage.vue"; // 导入购物车页面

const routes = [
  {
    path: "/",
    name: "Root",
    redirect: to => {
      const token = localStorage.getItem("token");
      return token ? "/home" : "/login";
    },
  },
  {
    path: "/login",
    name: "Login",
    component: Login,
    meta: { requiresGuest: true }, // 只允许未登录用户访问
  },
  {
    path: "/home",
    name: "Home",
    component: Home,
    meta: { requiresAuth: true }, // 需要登录才能访问
  },
  {
    path: "/register",
    name: "Register",
    component: Register,
    meta: { requiresGuest: true },
  },
  {
    path: "/forget-password",
    name: "ForgetPassword",
    component: ForgetPassword,
    meta: { requiresGuest: true },
  },
  {
    path: "/product/:id", // 添加商品详情页面路由
    name: "ProductPage",
    component: ProductPage,
    meta: { requiresAuth: true },
  },
  {
    path: "/userStore", // 添加个人中心页面路由
    name: "UserPage",
    component: UserPage,
    meta: { requiresAuth: true },
  },
  {
    path: "/orders", // 添加我的订单页面路由
    name: "OrderPage",
    component: OrderPage,
    meta: { requiresAuth: true },
  },
  {
    path: "/cart", // 添加购物车页面路由
    name: "CartPage",
    component: CartPage,
    meta: { requiresAuth: true },
  },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

// 路由守卫
router.beforeEach((to, from, next) => {
  const isAuthenticated = localStorage.getItem("token");

  // 需要登录的页面
  if (to.meta.requiresAuth && !isAuthenticated) {
    next("/login");
    return;
  }

  // 只允许未登录用户访问的页面（如登录、注册页）
  if (to.meta.requiresGuest && isAuthenticated) {
    next("/home");
    return;
  }

  next();
});

export default router;
